INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(31135, 0, 0, '瓦哈拉斯是你的胜利之地，也是你的葬身之地，$n。但无论你做什么，都要待在竞技场的范围内。逃跑就是失败，就是耻辱。', 12, 0, 100, 0, 0, 0, 31744, 0, 'Geirrvif - Fallen Heroes - On Quest Accept'),
(31135, 1, 0, '$n 与 $g 他的 : 她的; 战友们选择在瓦哈拉斯的神圣领域内接受荣誉之战。', 14, 0, 100, 0, 0, 0, 31745, 0, 'Geirrvif - Fallen Heroes - Announce Challengers'),
(31135, 2, 0, '这样的战斗只可能有一个结局：一方死去。让 $n 在那些倒下的外来者的尸骨上证明 $g 他自己 : 她自己; 吧！', 14, 0, 100, 0, 0, 0, 31746, 0, 'Geirrvif - Fallen Heroes - Announce Stakes'),
(31135, 3, 0, '瓦哈拉斯陨落的英雄们从地下钻出，再次投入战斗！', 41, 0, 100, 0, 0, 14998, 31756, 0, 'Geirrvif - Fallen Heroes - Announce Opponents Arrival'),
(31135, 4, 0, '$n 已击败瓦哈拉斯往昔战役中堕落的英雄们。这只是个开始，但已经足够了。', 14, 0, 100, 0, 0, 14998, 31755, 0, 'Geirrvif - Fallen Heroes - Announce Victory'),
(31135, 5, 0, '做好准备。基特里克斯将从东南方进入瓦哈拉斯。记住，不要离开战斗圈，否则你会输掉这场战斗。', 12, 0, 100, 0, 0, 0, 31771, 0, 'Geirrvif - Khit\'rix the Dark Master - On Quest Accept'),
(31135, 6, 0, '$n 已接受黑暗之主基特里克斯的挑战。愿诸神怜悯 $g 他 : 她;，因为基特里克斯肯定不会。', 14, 0, 100, 0, 0, 0, 31770, 0, 'Geirrvif - Khit\'rix the Dark Master - Announce Challengers'),
(31135, 7, 0, '黑暗之主基特里克斯从东南方窜进瓦哈拉斯！', 41, 0, 100, 0, 0, 14998, 32753, 0, 'Geirrvif - Khit\'rix the Dark Master - Announce Opponent Arrival'),
(31135, 8, 0, '$n 和 $g 他的 : 她的; 同伴们已经击败了黑暗之主基特里克斯。发出下一项挑战吧！', 14, 0, 100, 0, 0, 14998, 31820, 0, 'Geirrvif - Khit\'rix the Dark Master - Announce Victory'),
(31135, 9, 0, '西格丽德·冰裔已回到约顿海姆的高处，向 $n 证明自己。上次相遇时，$n 在单挑中击败了她。让我们看看这一战的结果。', 14, 0, 100, 0, 0, 0, 31892, 0, 'Geirrvif - The Return of Sigrid Iceborn - On Quest Accept'),
(31135, 10, 0, '西格丽德·冰裔正在瓦哈拉斯上空盘旋，前来寻仇！', 41, 0, 100, 0, 0, 14998, 32757, 0, 'Geirrvif - The Return of Sigrid Iceborn - Announce Opponent Arrival'),
(31135, 11, 0, '$n 第二次击败了西格丽德·冰裔。嗯，这次 $g 他 : 她; 是在 $g 他的 : 她的; 朋友帮助下做到的，但胜利就是胜利！', 14, 0, 100, 0, 0, 14998, 31921, 0, 'Geirrvif - The Return of Sigrid Iceborn - Announce Victory'),
(31135, 12, 0, '杀戮将至！记住，不管你们做什么，都不要离开战斗圈，否则我会取消你和你的队伍的资格。', 12, 0, 100, 0, 0, 0, 31885, 0, 'Geirrvif - Carnage! - On Quest Accept'),
(31135, 13, 0, '从地下大厅的深处来了「杀戮」。勇敢又愚蠢的 $n 接受了挑战。$G 他 : 她; 和 $g 他的 : 她的; 队伍已准备好面对那头怪物。', 14, 0, 100, 0, 0, 0, 31930, 0, 'Geirrvif - Carnage! - Announce Challengers'),
(31135, 14, 0, '他从南边笨重地走来，杀戮的气味先他而至！', 41, 0, 100, 0, 0, 14998, 32758, 0, 'Geirrvif - Carnage! - Announce Opponent Arrival'),
(31135, 15, 0, '名为「杀戮」的恐怖已不复存在。难道 $n 真的配在瓦哈拉斯战斗吗？我们拭目以待。', 14, 0, 100, 0, 0, 14998, 31931, 0, 'Geirrvif - Carnage! - Announce Victory'),
(31135, 16, 0, '看东南方，那个领主出现在无情者格约纳附近的平台上时你就看见了。让他下来。待在瓦哈拉斯的战斗圈内。', 12, 0, 100, 0, 0, 0, 31938, 0, 'Geirrvif - Thane Deathblow - On Quest Accept'),
(31135, 17, 0, '巴纳霍格领主时隔多年重返瓦哈拉斯，要证明维库人才是唯一配在这神圣战斗圈中战斗的种族。$n 能证明他错了吗？', 14, 0, 100, 0, 0, 0, 31939, 0, 'Geirrvif - Thane Deathblow - Announce Challengers'),
(31135, 18, 0, '巴纳霍格领主出现在东南方的高处！', 41, 0, 100, 0, 0, 14998, 32760, 0, 'Geirrvif - Thane Deathblow - Announce Opponent Arrival'),
(31135, 19, 0, '致命一击巴纳霍格领主已倒在 $n 和 $g 他的 : 她的; 战友手中。$G 他 : 她; 面前只剩一项挑战等着 $g 他 : 她;。会是谁？', 14, 0, 100, 0, 0, 14998, 31940, 0, 'Geirrvif - Thane Deathblow - Announce Victory'),
(31135, 20, 0, '现在跑已经太迟了。不要离开战斗圈。勇敢地死吧，$n！', 12, 0, 100, 0, 0, 0, 31949, 0, 'Geirrvif - Final Challenge - On Quest Accept'),
(31135, 21, 0, '冰冠堡垒的深处，巫妖王选中的一位前来终结 $n 和 $g 他的 : 她的; 朋友们的性命。', 14, 0, 100, 0, 0, 0, 31951, 0, 'Geirrvif - Final Challenge - Announce Challengers'),
(31135, 22, 0, '约顿海姆的战士们，我向你们引见血王子桑多瓦尔！', 14, 0, 100, 0, 0, 0, 31955, 0, 'Geirrvif - Final Challenge - Announce Opponent'),
(31135, 23, 0, '毫无预兆地，桑多瓦尔王子魔法般地出现在瓦哈拉斯！', 41, 0, 100, 0, 0, 14998, 32761, 0, 'Geirrvif - Final Challenge - Announce Opponent Arrival'),
(31135, 24, 0, '难以想象的事发生了……$n 杀死了桑多瓦尔王子！', 14, 0, 100, 0, 0, 0, 31945, 0, 'Geirrvif - Final Challenge - Announce Victory'),
(31135, 25, 0, '击败他之后，$g 他 : 她; 和 $g 他的 : 她的; 战友们证明了自己配得上在瓦哈拉斯这维库人最神圣的地方战斗。', 14, 0, 100, 0, 0, 0, 31946, 0, 'Geirrvif - Final Challenge - Announce Champion 1'),
(31135, 26, 0, '向 $n 致敬，瓦哈拉斯的勇士！', 14, 0, 100, 0, 0, 14998, 31948, 0, 'Geirrvif - Final Challenge - Announce Champion 2'),
(31135, 27, 0, '你还没准备好！', 14, 0, 100, 0, 0, 0, 31753, 0, 'Geirrvif - Announce Challenger Defeat');
